#!/bin/bash
# Generated by fishbowl. Applied once, as root, before CAP_NET_ADMIN is dropped.
#
# Every packet a non-gateway uid emits is either redirected to the gateway, where it is
# audited, or logged to NFLOG group {{ nflog_group }} and dropped. There is no third path,
# so an empty audit trail means the sandbox sent nothing rather than that something
# escaped unrecorded.
set -euo pipefail

readonly GATEWAY_UID={{ gateway_uid }}
readonly PROXY_PORT={{ proxy_port }}
readonly DNS_PORT={{ dns_port }}
readonly SSH_PORT={{ ssh_port }}
readonly NFLOG_GROUP={{ nflog_group }}

iptables -F
iptables -t nat -F
iptables -X || true
iptables -t nat -X || true

# Inbound: only the SSH control plane the host dials, plus replies to flows we allowed.
iptables -P INPUT DROP
iptables -A INPUT -i lo -j ACCEPT
iptables -A INPUT -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT
iptables -A INPUT -p tcp --dport "${SSH_PORT}" -j ACCEPT

# No routing between interfaces: the sandbox is an endpoint, never a relay.
iptables -P FORWARD DROP

# Outbound redirection. The gateway's own traffic is exempt, otherwise it would redirect
# into itself; every other uid is forced through it.
iptables -t nat -A OUTPUT -m owner --uid-owner "${GATEWAY_UID}" -j RETURN
iptables -t nat -A OUTPUT -o lo -j RETURN
iptables -t nat -A OUTPUT -p tcp -j REDIRECT --to-ports "${PROXY_PORT}"
iptables -t nat -A OUTPUT -p udp --dport 53 -j REDIRECT --to-ports "${DNS_PORT}"

iptables -P OUTPUT DROP
iptables -A OUTPUT -o lo -j ACCEPT
iptables -A OUTPUT -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT
iptables -A OUTPUT -m owner --uid-owner "${GATEWAY_UID}" -j ACCEPT

# The redirection above rewrote these packets' destination to the loopback address, but
# the outgoing interface this chain sees is still the one the original route chose, so
# `-o lo` never matches them. They are accepted by the destination the redirection gave
# them instead, which is exactly the gateway's two ports and nothing else.
iptables -A OUTPUT -p tcp -d 127.0.0.1 --dport "${PROXY_PORT}" -j ACCEPT
iptables -A OUTPUT -p udp -d 127.0.0.1 --dport "${DNS_PORT}" -j ACCEPT

# Nothing else is accepted by protocol. Traffic the redirection did not claim has no
# audited path and must not have an unaudited one, so a blanket `-p tcp -j ACCEPT` here
# would be the one hole in the policy.
# Anything still falling through is a transport the gateway cannot audit, most often QUIC.
# Record it per packet, then drop it so the client falls back to an auditable transport.
iptables -A OUTPUT -j NFLOG --nflog-group "${NFLOG_GROUP}" --nflog-prefix "fishbowl-blocked"
iptables -A OUTPUT -j DROP

# IPv6 has no audited path at all, so it is refused outright rather than left open.
ip6tables -P INPUT DROP
ip6tables -P FORWARD DROP
ip6tables -P OUTPUT DROP
ip6tables -A INPUT -i lo -j ACCEPT
ip6tables -A OUTPUT -o lo -j ACCEPT
ip6tables -I OUTPUT 2 -j NFLOG --nflog-group "${NFLOG_GROUP}" --nflog-prefix "fishbowl-blocked6"
